  for(let j=0;j<nby;j++) for(let i=0;i<nbx;i++){ let n=0; for(let y=j*B;y<Math.min(rh,(j+1)*B);y+=2) for(let x=i*B;x<Math.min(rw,(i+1)*B);x+=2){ if(excl(x,y)) continue; buf[n++]=R[y*rw+x]; } bg[j*nbx+i]=n>=12?pct(buf,n,q):bgN; }
