    const keep=cs.filter(c=>c.n>=2&&c.y1-c.y0+1<=120&&c.x1-c.x0+1<=180); if(keep.length<2||keep.length>4000) continue;
    const gs=stackMerge(keep); const Ls=lines(gs).filter(l=>l.length>=2&&l.length<=40);
