OCR.findBar=function(img,w,h,opt){ const b=OCR.findBars(img,w,h,opt); return b.length?b[0]:null; };
/* 막대 힌트(DIFF_PATTERN.scaleBar) + 스스로 찾은 막대들로 읽어 conf 가 가장 높은 것. 결과에 bar 를 붙인다 */
